corrected_code:
app.post('/api/auth/device-session/refresh', async (req, res) => {
  const { deviceFingerprint, refreshToken } = req.body;

  const tokenRecord = await prisma.refreshToken.findUnique({
    where: { token: refreshToken },
    include: { deviceSession: true }
  });
  if (!tokenRecord || tokenRecord.expiresAt < new Date()) {
    return res.status(401).json({ error: 'Expired or missing refresh token' });
  }

  if (tokenRecord.deviceSession.primaryFingerprint !== deviceFingerprint) {
    await prisma.refreshToken.delete({ where: { token: refreshToken } });
    return res.status(403).json({ error: 'Device fingerprint mismatch. Refresh token revoked.' });
  }

  await prisma.deviceSession.update({
    where: { id: tokenRecord.deviceSessionId },
    data: { lastSeen: new Date() }
  });

  const newAccessToken = generateAccessToken(tokenRecord.userId);
  res.json({ accessToken: newAccessToken });
});
